public class MustacheLiteTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            MustacheLite engine = new MustacheLite().set("name", "Ada").set("lang", "Java");
            check("simple placeholder", "Hello Ada!", engine.render("Hello {{name}}!"));
            check("spaces inside braces", "Hi Ada, welcome", engine.render("Hi {{ name }}, welcome"));
            check("two placeholders", "Ada writes Java", engine.render("{{name}} writes {{lang}}"));
            check("unknown key copied verbatim", "{{age}}Ada", engine.render("{{age}}{{name}}"));
            check("no placeholders at all", "plain text", engine.render("plain text"));
            check("unclosed braces", "open {{ oops", engine.render("open {{ oops"));
            check("set returns this for chaining", "1-2",
                    new MustacheLite().set("a", "1").set("b", "2").render("{{a}}-{{b}}"));
            check("last set wins", "second", new MustacheLite().set("k", "first").set("k", "second").render("{{k}}"));
            check("missingKeys in order, no dupes", "[x, y]",
                    engine.missingKeys("{{x}} {{name}} {{ x }} {{y}}").toString());
        } catch (Throwable t) {
            broke("MustacheLite", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

