import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class MustacheLite {

    private final Map<String, String> values = new LinkedHashMap<>();

    public MustacheLite set(String key, String value) {
        values.put(key, value);
        return this;
    }

    public String render(String template) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < template.length()) {
            int open = template.indexOf("{{", i);
            if (open < 0) {
                out.append(template.substring(i));
                break;
            }
            int close = template.indexOf("}}", open + 2);
            if (close < 0) {
                out.append(template.substring(i));
                break;
            }
            out.append(template, i, open);
            String key = template.substring(open + 2, close).trim();
            if (values.containsKey(key)) {
                out.append(values.get(key));
            } else {
                out.append(template, open, close + 2);
            }
            i = close + 2;
        }
        return out.toString();
    }

    public List<String> missingKeys(String template) {
        List<String> missing = new ArrayList<>();
        int i = 0;
        while (i < template.length()) {
            int open = template.indexOf("{{", i);
            if (open < 0) {
                break;
            }
            int close = template.indexOf("}}", open + 2);
            if (close < 0) {
                break;
            }
            String key = template.substring(open + 2, close).trim();
            if (!values.containsKey(key) && !missing.contains(key)) {
                missing.add(key);
            }
            i = close + 2;
        }
        return missing;
    }
}
